const FORM_WORDS = new Set([
  "oral", "tablet", "tablets", "tab", "tabs", "capsule", "capsules", "cap", "solution", "suspension", "injection",
  "injectable", "pen", "injector", "auto-injector", "prefilled", "syringe", "inhaler", "inhalation", "aerosol",
