      const s = strengthOf(drugName);''')
s=s.replace('''function doseFromSig(sig: string, drugName: string, combo: boolean)''','''function doseFromSig(sig: string, drugName: string, combo: boolean, ingredient?: string)''')
s=s.replace('''return doseFrom({ value: v, unit: m[2] }, drugName, combo);''','''return doseFrom({ value: v, unit: m[2] }, drugName, combo, ingredient);''')
