    if (!d && !dose && sig) d = doseFromSig(sig, drugName, combo);
    void sigDose;
''','''    const doseFor = (ing: string | undefined) => {
      let d = doseFrom(dose, drugName!, combo, ing);
      if (!d && !dose && sig) d = doseFromSig(sig, drugName!, combo, ing);
      return d;
    };
''')
